import {playKolomFrames} from './kolom-jrpg-animation.js';
import {act} from './game.js';
import {manualBattleBody,manualFieldPrefs} from './kolom-jrpg.js';
import {PREVIEW_BATTLES,previewCombat,previewRoute,createBattlePreview} from './jrpg-preview-fixtures.js';
const root=document.querySelector('#battle'),key='station-jrpg-sandbox-v2';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
let kind=PREVIEW_BATTLES[saved?.kind]?saved.kind:'kolom',guarded=saved?.guarded??true,state=saved?.state??createBattlePreview(kind,{guarded});
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const a=state.interactiveMission,c=previewCombat(state);root.innerHTML='<section class="panel"><label>Пробный бой <select id="preview-kind">'+Object.entries(PREVIEW_BATTLES).map(([id,name])=>'<option value="'+id+'" '+(id===kind?'selected':'')+'>'+name+'</option>').join('')+'</select></label>'+(kind==='roof'?'<label><input type="checkbox" id="preview-guards" '+(guarded?'checked':'')+'> Охрана SM · два союзника</label>':'')+'<p class="muted">Отдельное тестовое сохранение. Основная игра не изменяется.</p><button data-action="previewReset">Начать бой заново</button></section>'+(c?manualBattleBody({...a,combat:c,battleTitle:kind==='kolom'?undefined:PREVIEW_BATTLES[kind]},state.heroes):'<section class="panel"><h2>Бой завершён</h2></section>')+(c&&!['pending','running'].includes(c.status)?'<section class="panel"><h2>'+esc(({recovery:'Победа · лечение доступно в вылазке',casualty:'Герой повержен — бой на паузе',victory:'Победа',escaped:'Отряд отступил',defeat:'Отряд повержен'})[c.status]??c.status)+'</h2>'+c.heroes.map(h=>'<p>'+esc(h.name)+' · '+Math.max(0,Math.round(h.hp))+' HP</p>').join('')+(c.status==='casualty'?'<button data-action="previewContinue">Драться до последнего</button>':'')+'<details><summary>Ход боя</summary>'+c.events.map(e=>'<p>'+esc(e.text??e.type)+'</p>').join('')+'</details></section>':'');}
function save(){localStorage.setItem(key,JSON.stringify({kind,guarded,state}));}
function restart(){state=createBattlePreview(kind,{guarded});save();render();}
function commit(action){try{const previous=previewCombat(state);state=act(state,action);save();render();playKolomFrames(root,previous,previewCombat(state));}catch(e){const n=document.querySelector('#announcement');n.className='';n.textContent=e.message;}}
root.addEventListener('change',event=>{if(event.target.id==='preview-kind'){kind=event.target.value;restart();return;}if(event.target.id==='preview-guards'){guarded=event.target.checked;restart();return;}const field=event.target.dataset.jrpgField;if(field)commit({...previewRoute(state,true),prefs:manualFieldPrefs(previewCombat(state)?.heroes.find(h=>h.id===previewCombat(state).waitingHeroId),field,event.target.value)});});
root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const action=b.dataset.action;if(action==='previewReset'){restart();return;}if(action==='previewContinue'){const a=state.interactiveMission;commit(a.id==='kolomenskaya'?{type:'kolomChoice',node:'casualty',choice:'fight'}:a.id==='hansaRoute'?{type:'hansaRouteChoice',node:a.node,choice:'turn'}:{type:'interactiveBattleDecision',decision:'fight'});return;}const c=previewCombat(state),hero=c?.heroes.find(h=>h.id===c.waitingHeroId);if(!hero)return;const prefs=hero.manualPrefs??{},commandKind=b.dataset.kind??prefs.kind??'attack';if(action==='jrpgTarget'){commit({...previewRoute(state,true),prefs:{targetId:b.dataset.id}});return;}if(action==='jrpgSelect'&&!(prefs.armed&&commandKind===(prefs.kind??'attack'))){commit({...previewRoute(state,true),prefs:{kind:commandKind,armed:true}});return;}if(!['jrpgSelect','jrpgExecute'].includes(action))return;const value=field=>root.querySelector('[data-jrpg-field="'+field+'"]')?.value;commit({...previewRoute(state),command:{revision:c.manualRevision??0,kind:commandKind,slot:value('slot'),mode:value('mode'),aim:value('aim'),item:value('item'),targetId:commandKind==='heal'?value('patient'):(c.enemies.find(e=>e.id===prefs.targetId&&e.hp>0)??c.enemies.find(e=>e.hp>0))?.id}});});
render();
